            (
                4UL
                + FfiConverterTypeFfiDeviceInfo.allocationSize(value.`peer`)
            )
        }
        is FfiSyncEvent.Disconnected -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`peerId`)
                + FfiConverterString.allocationSize(value.`peerName`)
            )
        }
        is FfiSyncEvent.ClipboardReceived -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`fromName`)
            )
        }
        is FfiSyncEvent.ClipboardBroadcast -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUInt.allocationSize(value.`peerCount`)
            )
        }
        is FfiSyncEvent.FileReceiving -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`transferId`)
                + FfiConverterString.allocationSize(value.`fromName`)
                + FfiConverterString.allocationSize(value.`fileName`)
                + FfiConverterULong.allocationSize(value.`sizeBytes`)
            )
        }
        is FfiSyncEvent.FileReceived -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`transferId`)
                + FfiConverterString.allocationSize(value.`fileName`)
                + FfiConverterString.allocationSize(value.`path`)
            )
        }
        is FfiSyncEvent.FileSent -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`transferId`)
                + FfiConverterString.allocationSize(value.`fileName`)
                + FfiConverterString.allocationSize(value.`toName`)
            )
        }
        is FfiSyncEvent.FileTransferFailed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`transferId`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
        is FfiSyncEvent.Error -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
        }
        is FfiSyncEvent.WasReset -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is FfiSyncEvent.PausedStateChanged -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterBoolean.allocationSize(value.`paused`)
            )
        }
        is FfiSyncEvent.ReconnectFailed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`peerId`)
            )
        }
        is FfiSyncEvent.NowPlayingChanged -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`peerId`)
                + FfiConverterString.allocationSize(value.`peerName`)
                + FfiConverterTypeFfiNowPlayingInfo.allocationSize(value.`info`)
            )
        }
    }

    override fun write(value: FfiSyncEvent, buf: ByteBuffer) {
        when(value) {
            is FfiSyncEvent.Listening -> {
                buf.putInt(1)
                FfiConverterUShort.write(value.`port`, buf)
                Unit
            }
            is FfiSyncEvent.PairingRequested -> {
                buf.putInt(2)
                FfiConverterTypeFfiDeviceInfo.write(value.`peer`, buf)
                FfiConverterString.write(value.`code`, buf)
                Unit
            }
            is FfiSyncEvent.Paired -> {
                buf.putInt(3)
                FfiConverterTypeFfiDeviceInfo.write(value.`peer`, buf)
                Unit
            }
            is FfiSyncEvent.PairingDeclined -> {
                buf.putInt(4)
                FfiConverterString.write(value.`peerName`, buf)
                Unit
            }
            is FfiSyncEvent.Connected -> {
                buf.putInt(5)
                FfiConverterTypeFfiDeviceInfo.write(value.`peer`, buf)
                Unit
            }
            is FfiSyncEvent.Disconnected -> {
                buf.putInt(6)
                FfiConverterString.write(value.`peerId`, buf)
                FfiConverterString.write(value.`peerName`, buf)
                Unit
            }
            is FfiSyncEvent.ClipboardReceived -> {
                buf.putInt(7)
                FfiConverterString.write(value.`fromName`, buf)
                Unit
            }
            is FfiSyncEvent.ClipboardBroadcast -> {
                buf.putInt(8)
                FfiConverterUInt.write(value.`peerCount`, buf)
                Unit
            }
            is FfiSyncEvent.FileReceiving -> {
                buf.putInt(9)
                FfiConverterString.write(value.`transferId`, buf)
                FfiConverterString.write(value.`fromName`, buf)
                FfiConverterString.write(value.`fileName`, buf)
                FfiConverterULong.write(value.`sizeBytes`, buf)
                Unit
            }
            is FfiSyncEvent.FileReceived -> {
                buf.putInt(10)
                FfiConverterString.write(value.`transferId`, buf)
                FfiConverterString.write(value.`fileName`, buf)
                FfiConverterString.write(value.`path`, buf)
                Unit
            }
            is FfiSyncEvent.FileSent -> {
                buf.putInt(11)
                FfiConverterString.write(value.`transferId`, buf)
                FfiConverterString.write(value.`fileName`, buf)
                FfiConverterString.write(value.`toName`, buf)
                Unit
            }
            is FfiSyncEvent.FileTransferFailed -> {
                buf.putInt(12)
                FfiConverterString.write(value.`transferId`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is FfiSyncEvent.Error -> {
                buf.putInt(13)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is FfiSyncEvent.WasReset -> {
                buf.putInt(14)
                Unit
            }
            is FfiSyncEvent.PausedStateChanged -> {
                buf.putInt(15)
                FfiConverterBoolean.write(value.`paused`, buf)
                Unit
            }
            is FfiSyncEvent.ReconnectFailed -> {
                buf.putInt(16)
                FfiConverterString.write(value.`peerId`, buf)
                Unit
            }
            is FfiSyncEvent.NowPlayingChanged -> {
                buf.putInt(17)
                FfiConverterString.write(value.`peerId`, buf)
                FfiConverterString.write(value.`peerName`, buf)
                FfiConverterTypeFfiNowPlayingInfo.write(value.`info`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






/**
 * @suppress
 */
public object FfiConverterOptionalString: FfiConverterRustBuffer<kotlin.String?> {
    override fun read(buf: ByteBuffer): kotlin.String? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterString.read(buf)
    }

    override fun allocationSize(value: kotlin.String?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterString.allocationSize(value)
        }
    }

    override fun write(value: kotlin.String?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterString.write(value, buf)
        }
    }
}
